INSERT INTO rights_wording (row_id, unique_row, old_key, new_key, fields, en, note)
VALUES
  (1, true, '1|||קצבת נכות למתמודדי נפש', '1|||עמוד שמרכז את הקצבאות וההטבות למי שמתמודד עם בעיה נפשית. באתר.', '{"org":"ביטוח לאומי","svc":"עמוד שמרכז את הקצבאות וההטבות למי שמתמודד עם בעיה נפשית. באתר.","target":"מי שמתמודד עם בעיה נפשית","region":"כל הארץ","cost":"ביטוח לאומי","specialty":"","approaches":"","languages":"","diseases":"","notes":"שירותים מיוחדים, גמלת סיעוד, יד מכוונת וסל השיקום בכרטיסים נפרדים.","meeting":"","web":"https://www.btl.gov.il/ZcuyotAsdience/MitmoddiNefesh/Pages/default.aspx","phone":"*6050","phoneLabel":"מוקד","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"National Insurance Institute","svc":"A page that gathers the benefits and allowances for a person coping with a mental problem. On the site.","target":"A person coping with a mental problem","region":"Nationwide","cost":"The National Insurance Institute","notes":"Special services, the nursing benefit, Yad Mechavenet, and the rehabilitation basket are on separate cards.","phone":"*6050","phoneLabel":"Hotline","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול עמוד מתמודדים עם בעיה נפשית באתר הביטוח הלאומי. 04-8812345 הוא אותו מוקד ולא עלה. הניסוח אושר עם אצוות הזכויות.'),
  (2, true, '2|||שירותים מיוחדים (שר"מ)', '2|||קצבת שירותים מיוחדים למי שזקוק לעזרה רבה ביום-יום, או להשגחה מתמדת. באתר.', '{"org":"ביטוח לאומי","svc":"קצבת שירותים מיוחדים למי שזקוק לעזרה רבה ביום-יום, או להשגחה מתמדת. באתר.","target":"מבוגרים עד גיל פרישה","region":"כל הארץ","cost":"ביטוח לאומי","specialty":"","approaches":"","languages":"","diseases":"","notes":"גם למי שלא מקבל קצבת נכות, אם נקבעה נכות רפואית של 75% לפחות. מי שמאושפז במוסד עם שירותי רפואה, סיעוד או שיקום אינו זכאי. ההסבר של כל זכות בכרטיס נפרד.","meeting":"","web":"https://www.btl.gov.il/benefits/Attendance_Allowance/Pages/default.aspx","phone":"*6050","phoneLabel":"מוקד","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"National Insurance Institute","svc":"A special-services benefit for a person who needs a lot of help with daily activities, or constant supervision. On the site.","target":"Adults up to retirement age","region":"Nationwide","cost":"The National Insurance Institute","notes":"Also for a person who does not receive a disability benefit, if a medical disability of at least 75 percent was set. A person hospitalized in an institution with medical, nursing, or rehabilitation services is not eligible. The Kol Zchut explanation is on a separate card.","phone":"*6050","phoneLabel":"Hotline","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול עמוד שירותים מיוחדים לנכים. הסכומים לא עלו. הניסוח אושר עם אצוות הזכויות.'),
  (3, true, '3|||קצבת סיעוד', '3|||גמלת סיעוד למי שהגיע לגיל פרישה, גר בבית, וזקוק לעזרה ביום-יום. באתר.', '{"org":"ביטוח לאומי","svc":"גמלת סיעוד למי שהגיע לגיל פרישה, גר בבית, וזקוק לעזרה ביום-יום. באתר.","target":"מי שהגיע לגיל פרישה","region":"כל הארץ","cost":"ביטוח לאומי","specialty":"","approaches":"","languages":"","diseases":"","notes":"גם למי שזקוק להשגחה צמודה. אפשר לקבל את הגמלה בכסף, בשירותים, או בשניהם. יש שש רמות.","meeting":"","web":"https://www.btl.gov.il/benefits/Long_Term_Care/Pages/default.aspx","add":"https://www.kolzchut.org.il/he/%D7%92%D7%9E%D7%9C%D7%AA_%D7%A1%D7%99%D7%A2%D7%95%D7%93","addLabel":"כל זכות","phone":"*2637","phoneLabel":"מוקד","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"National Insurance Institute","svc":"A nursing benefit for a person who has reached retirement age, lives at home, and needs help with daily activities. On the site.","target":"A person who has reached retirement age","region":"Nationwide","cost":"The National Insurance Institute","notes":"Also for a person who needs close supervision. The benefit can be taken in money, in services, or in both. There are six levels.","addLabel":"Kol Zchut","phone":"*2637","phoneLabel":"Hotline","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול עמוד הסיעוד. *2637 מפורסם שם לבירורים. הקישור לכל זכות נשאר. הניסוח אושר עם אצוות הזכויות.'),
  (4, true, '4|||ייעוץ והכנה בחינם לוועדה הרפואית', '4|||ייעוץ והכנה לוועדה הרפואית. בחינם, בטלפון.', '{"org":"יד מכוונת","svc":"ייעוץ והכנה לוועדה הרפואית. בחינם, בטלפון.","target":"מי שמגיש תביעה, זומן לוועדה, או מגיש ערר","region":"כל הארץ","cost":"ללא עלות","specialty":"","approaches":"","languages":"","diseases":"","notes":"לנכות כללית, נפגעי עבודה, נפגעי איבה, שירותים מיוחדים, ילד נכה, ופטור ממס הכנסה.","meeting":"","web":"https://www.btl.gov.il/snifim/Pages/yadMechavenet1.aspx","phone":"*2496","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Yad Mechavenet","svc":"Advice and preparation for the medical committee. Free of charge, by phone.","target":"A person filing a claim, summoned to the committee, or filing an appeal","region":"Nationwide","cost":"At no cost","notes":"For general disability, work injuries, victims of hostilities, special services, a disabled child, and an income-tax exemption.","phone":"*2496","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול עמוד יד מכוונת. הפגישה נקבעת ב-*2496. הניסוח אושר עם אצוות הזכויות.'),
  (5, true, '5|||סל שיקום', '5|||סל שירותי שיקום בקהילה: דיור, תעסוקה, פנאי, השכלה וליווי. בקהילה.', '{"org":"משרד הבריאות","svc":"סל שירותי שיקום בקהילה: דיור, תעסוקה, פנאי, השכלה וליווי. בקהילה.","target":"בני 18 ומעלה עם 40% נכות נפשית לפחות","region":"כל הארץ","cost":"משרד הבריאות","specialty":"","approaches":"","languages":"","diseases":"","notes":"אפשר גם במסלול אישי, בלי הכרה בביטוח הלאומי. מי שמכור לסמים או לאלכוהול יכול לקבל את הסל רק אחרי גמילה. אתר סל שיקום וכל זכות בכרטיסים נפרדים.","meeting":"","web":"https://me.health.gov.il/mental-health/therapy-rehabilitation/rehabilitation/rehabilitation-basket/about/","add":"https://www.gov.il/he/service/rehabilitation-support-package","addLabel":"הגשת בקשה","phone":"*5400","phoneLabel":"משרד הבריאות","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Ministry of Health","svc":"A basket of community rehabilitation services: housing, employment, leisure, education, and accompaniment. In the community.","target":"People aged 18 and over with a mental disability of at least 40 percent","region":"Nationwide","cost":"The Ministry of Health","notes":"There is also a personal track, without recognition by the National Insurance Institute. A person addicted to drugs or alcohol can receive the basket only after withdrawal. The rehabilitation-basket site and Kol Zchut are on separate cards.","addLabel":"Submit an application","phone":"*5400","phoneLabel":"Ministry of Health","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול עמוד הזכאות לסל שיקום מ-24.11.2026. *5400 מפורסם שם. 08-6241010 הוא אותו קו ולא עלה. הניסוח אושר עם אצוות הזכויות.'),
  (57, true, '57|||קבוצה בפייסבוק', '57|||קבוצה בפייסבוק לשיחה על סל שיקום.', '{"org":"מדברים על סל שיקום","svc":"קבוצה בפייסבוק לשיחה על סל שיקום.","target":"","region":"","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"","meeting":"","web":"https://www.facebook.com/groups/1391071081763987/","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Talking About the Rehabilitation Basket","svc":"A Facebook group for conversation about the rehabilitation basket.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: עמוד הקבוצה לא נפתח. הניסוח הוא לפי שם הקבוצה. הניסוח אושר עם אצוות הזכויות.'),
  (68, true, '68|||סיוע למשפחות של מתמודדי נפש', '68|||ליווי במיצוי זכויות ובהכנה לסל שיקום. במרכז.', '{"org":"בלב ובנפש","svc":"ליווי במיצוי זכויות ובהכנה לסל שיקום. במרכז.","target":"בני 18 ומעלה","region":"בני ברק, פתח תקווה, אלעד, ראש העין, מודיעין עילית, ביתר, ירושלים, בית שמש, חיפה","cost":"ללא עלות","specialty":"","approaches":"","languages":"","diseases":"","notes":"של עזר מציון. אין תנאי סף. המשרד ברב רבינוב 5, בני ברק. הטלפון של ירושלים הוא גם לבית שמש ולביתר.","meeting":"in_person","web":"https://www.ami.org.il/services/with-heart-and-soul","phone":"073-3956204","phoneLabel":"מרכז","phoneShowNumber":false,"phone2":"052-7115241","phoneLabel2":"ירושלים","phoneShowNumber2":false,"phone3":"052-3204394","phoneLabel3":"צפון","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Balev BaNefesh","svc":"Accompaniment in realizing rights and in preparing for the rehabilitation basket. At the center.","target":"People aged 18 and over","region":"Bnei Brak, Petah Tikva, Elad, Rosh HaAyin, Modiin Illit, Beitar, Jerusalem, Beit Shemesh, Haifa","cost":"At no cost","notes":"Part of Ezer Mizion. There is no eligibility threshold. The office is at 5 Rav Rabinovich, Bnei Brak. The Jerusalem phone is also for Beit Shemesh and Beitar.","meeting":"in_person","phone":"073-3956204","phoneLabel":"Center","phone2":"052-7115241","phoneLabel2":"Jerusalem","phone3":"052-3204394","phoneLabel3":"North","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול https://www.ami.org.il/services/with-heart-and-soul. השירות לבני 18 ומעלה וללא תשלום. מרכזי המשפחות הם שירות אחר ולא עלו. הניסוח אושר עם אצוות הזכויות.'),
  (82, true, '82|||קביעת נכות למתמודדי נפש', '82|||הסבר על קביעת נכות רפואית על רקע נפשי. באתר.', '{"org":"כל זכות","svc":"הסבר על קביעת נכות רפואית על רקע נפשי. באתר.","target":"בני 18 ומעלה","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"אפשר בוועדה של הביטוח הלאומי, או אצל פסיכיאטר שהוסמך, במסלול אישי לסל שיקום בלבד. המסלול האישי ללא תשלום, ומי שכבר פנה לביטוח הלאומי לא יכול לבחור בו.","meeting":"","web":"https://www.kolzchut.org.il/he/%D7%A7%D7%91%D7%99%D7%A2%D7%AA_%D7%A0%D7%9B%D7%95%D7%AA_%D7%9C%D7%9E%D7%AA%D7%9E%D7%95%D7%93%D7%93%D7%99_%D7%A0%D7%A4%D7%A9","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Kol Zchut","svc":"An explanation of how a medical disability on psychiatric grounds is determined. On the site.","target":"People aged 18 and over","region":"Nationwide","notes":"It can be done at a National Insurance committee, or by a psychiatrist who was authorized, on the personal track for the rehabilitation basket only. The personal track is free of charge, and a person who already applied to the National Insurance Institute cannot choose it.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול עמוד קביעת הנכות בכל זכות. הניסוח אושר עם אצוות הזכויות.'),
  (83, false, '83|||קצבת שירותים מיוחדים למתמודדי נפש', '83|||הסבר על קצבת שירותים מיוחדים למי שזקוק לעזרה רבה ביום-יום. באתר.', '{"org":"כל זכות","svc":"הסבר על קצבת שירותים מיוחדים למי שזקוק לעזרה רבה ביום-יום. באתר.","target":"מבוגרים עד גיל פרישה","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"הסכומים לא כאן. העמוד של הביטוח הלאומי בכרטיס נפרד.","meeting":"","web":"https://www.kolzchut.org.il/he/%D7%A7%D7%A6%D7%91%D7%AA_%D7%A9%D7%99%D7%A8%D7%95%D7%AA%D7%99%D7%9D_%D7%9E%D7%99%D7%95%D7%97%D7%93%D7%99%D7%9D","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Kol Zchut","svc":"An explanation of the special-services benefit for a person who needs a lot of help with daily activities. On the site.","target":"Adults up to retirement age","region":"Nationwide","notes":"The amounts are not here. The National Insurance page is on a separate card.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול עמוד שירותים מיוחדים בכל זכות. הסכומים לשנת 2026 לא עלו. כרטיס ההסעות באותה שורה לא נגע. הניסוח אושר עם אצוות הזכויות.'),
  (84, false, '84|||סל שיקום למתמודדי נפש', '84|||הסבר על סל השיקום של משרד הבריאות. באתר.', '{"org":"כל זכות","svc":"הסבר על סל השיקום של משרד הבריאות. באתר.","target":"בני 18 ומעלה עם 40% נכות נפשית לפחות","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"העמוד של משרד הבריאות ואתר סל שיקום בכרטיסים נפרדים.","meeting":"","web":"https://www.kolzchut.org.il/he/%D7%A1%D7%9C_%D7%A9%D7%99%D7%A7%D7%95%D7%9D_%D7%9C%D7%9E%D7%AA%D7%9E%D7%95%D7%93%D7%93%D7%99_%D7%A0%D7%A4%D7%A9","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Kol Zchut","svc":"An explanation of the Ministry of Health rehabilitation basket. On the site.","target":"People aged 18 and over with a mental disability of at least 40 percent","region":"Nationwide","notes":"The Ministry of Health page and the rehabilitation-basket site are on separate cards.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול עמוד סל שיקום בכל זכות, שעודכן ב-29.07.2025. כרטיס ההסעות באותה שורה לא נגע. הניסוח אושר עם אצוות הזכויות.'),
  (85, true, '85|||מדריך מיצוי זכויות למתמודדי נפש ובני משפחותיהם', '85|||מדריך שאלות למיצוי זכויות למתמודדים ולבני משפחה. באתר.', '{"org":"כל זכות","svc":"מדריך שאלות למיצוי זכויות למתמודדים ולבני משפחה. באתר.","target":"מתמודדים ובני משפחה","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"המדריך מפנה לביטוח הלאומי, לסל שיקום, לנפגעי איבה ולמשרד הביטחון.","meeting":"","web":"https://www.kolzchut.org.il/he/%D7%9E%D7%93%D7%A8%D7%99%D7%9A_%D7%9E%D7%99%D7%A6%D7%95%D7%99_%D7%96%D7%9B%D7%95%D7%99%D7%95%D7%AA_%D7%9C%D7%9E%D7%AA%D7%9E%D7%95%D7%93%D7%93%D7%99_%D7%A0%D7%A4%D7%A9_%D7%95%D7%91%D7%A0%D7%99_%D7%9E%D7%A9%D7%A4%D7%97%D7%95%D7%AA%D7%99%D7%94%D7%9D","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Kol Zchut","svc":"A question guide for realizing rights, for people coping with mental illness and for family members. On the site.","target":"People coping with mental illness, and family members","region":"Nationwide","notes":"The guide points to the National Insurance Institute, the rehabilitation basket, victims of hostilities, and the Ministry of Defense.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול מדריך מיצוי הזכויות בכל זכות. הניסוח אושר עם אצוות הזכויות.'),
  (776, true, '776|||חוברת זכויות בריאות הנפש', '776|||חוברת על זכויות בביטוח הלאומי, בסל שיקום, בדיור, בתעסוקה ובאשפוז. בקובץ.', '{"org":"חוברת זכויות בריאות הנפש","svc":"חוברת על זכויות בביטוח הלאומי, בסל שיקום, בדיור, בתעסוקה ובאשפוז. בקובץ.","target":"מתמודדים, בני משפחה, ואנשי צוות","region":"כל הארץ","cost":"חינם","specialty":"","approaches":"","languages":"עברית","diseases":"","notes":"כתבה מיכל יום טוב, עובדת סוציאלית קלינית במרכז לבריאות הנפש לב השרון. הקובץ מנובמבר 2022, ולא כל האפשרויות מופיעות בו.","meeting":"","web":"","add":"/downloads/חוברת-זכויות-לב-השרון.pdf","addLabel":"הורדת החוברת (PDF)","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Mental Health Rights Booklet","svc":"A booklet on rights in the National Insurance Institute, in the rehabilitation basket, in housing, in employment, and in hospitalization. In a file.","target":"People coping with mental illness, family members, and staff","region":"Nationwide","cost":"Free","languages":"Hebrew","notes":"Written by Michal Yom Tov, a clinical social worker at the Lev HaSharon Mental Health Center. The file is from November 2022, and it does not include every option.","addLabel":"Download the booklet","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול החוברת עצמה. הקובץ נוצר בנובמבר 2022. המשפט שזו אינה ייעוץ ירד. הניסוח אושר עם אצוות הזכויות.');

UPDATE site_audit_entries s
SET card_keys = (
  SELECT COALESCE(array_agg(
    COALESCE((SELECT w.new_key FROM rights_wording w WHERE w.old_key = k), k)
    ORDER BY ord
  ), '{}')
  FROM unnest(s.card_keys) WITH ORDINALITY AS u(k, ord)
)
WHERE EXISTS (
  SELECT 1
  FROM unnest(s.card_keys) k
  JOIN rights_wording w ON w.old_key = k
);

UPDATE directory_card_edits c
SET card_key = w.new_key,
    public_fields = COALESCE(c.public_fields, '{}'::jsonb) || w.fields,
    translations = jsonb_set(
      COALESCE(c.translations, '{}'::jsonb),
      '{en}',
      COALESCE(c.translations->'en', '{}'::jsonb) || w.en,
      true
    ),
    eligibility = jsonb_set(
      COALESCE(c.eligibility, '{}'::jsonb),
      '{internal_notes}',
      to_jsonb(
        CASE
          WHEN COALESCE(c.eligibility->>'internal_notes', '') = '' THEN w.note
          ELSE rtrim(c.eligibility->>'internal_notes') || E'\n\n' || w.note
        END
      ),
      true
    ),
    public_edited_at = now(),
    updated_at = now()
FROM rights_wording w
WHERE c.card_key = w.old_key
   OR (
     w.unique_row
     AND c.row_id = w.row_id
     AND (SELECT count(*) FROM directory_card_edits d WHERE d.row_id = w.row_id) = 1
   );

UPDATE directory_entries e
SET display_name = c.public_fields->>'org',
    description = c.public_fields->>'svc'
FROM directory_card_edits c
JOIN rights_wording w ON w.new_key = c.card_key
WHERE e.entry_id = c.entry_id;

COMMIT;
